{"packet_id":"D041-01","doc_id":"D041","jurisdiction":"Los Angeles, CA","category":"rent_increase_limits","lifecycle":"enacted","title":"Los Angeles RSO allowable rent increase","requirement":"RSO rent may rise only once every 12 months, at the allowable percentage; since February 2, 2026 no utility percentage or 10% dependent increase may be added. Capital improvement, renovation, seismic, rehabilitation and just-and-reasonable increases need LAHD approval.","key_value":"Once every 12 months at the allowable rent increase percentage; utility add-on eliminated 2026-02-02","coverage_conditions":"Rental units in the City of Los Angeles first built on or before October 1, 1978, including apartments, condominiums, townhomes, duplexes, ADUs, mobile homes and hotel rooms occupied 30+ days, plus replacement units.","applicability":{"built_on_or_before":"1978-10-01","built_after":null,"date_basis":"construction_date","min_units":null,"max_units":null,"owner_dependent":false,"other":"Replacement units under LAMC Section 151.28 are also covered"},"exemptions":"Condominium and townhome tenancies that commenced after December 31, 1995 (rent amount not regulated); units not first built on or before October 1, 1978; luxury exemption where rent charged on or before May 31, 1978 met the threshold.","penalty":null,"effective_date":"2026-02-02","citation":"Los Angeles Rent Stabilization Ordinance (L.A.M.C. §151.00 et seq.)","quoted_span":"Effective February 2, 2026, the landlord can no longer include an additional percentage increase for utilities. Effective March 30, 2020, through January 31, 2024, rent increases are prohibited for rental units subject to the Rent Stabilization Ordinance (RSO).","interaction":null,"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D041-01","doc_id":"D041","jurisdiction":"Los Angeles, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Los Angeles RSO legal reasons for eviction","requirement":"An RSO tenancy may end only for at-fault causes (nonpayment, lease violation, nuisance, illegal use, refusal to renew) or no-fault causes (owner move-in, demolition, government order); no-fault evictions require relocation assistance and eviction notices must be filed with LAHD within three business days.","key_value":"30-day and 60-day notice; relocation assistance for no-fault evictions","coverage_conditions":"Rental units in the City of Los Angeles subject to the Rent Stabilization Ordinance, i.e. first built on or before October 1, 1978, plus replacement units.","applicability":{"built_on_or_before":"1978-10-01","built_after":null,"date_basis":"construction_date","min_units":null,"max_units":null,"owner_dependent":false,"other":null},"exemptions":"Units not subject to the RSO; those tenancies fall under the City's Just Cause Ordinance instead.","penalty":null,"effective_date":null,"citation":"L.A.M.C. § 151.09","quoted_span":"No-fault evictions require the payment of relocation assistance.","interaction":"The City's Just Cause Ordinance covers rental units not covered by the RSO.","confidence":0.8,"conflict_flag":false,"conflict_note":null}
